const counter = {
  count: 0,
  bump(step) {
    this.count += step;
    return this.count;
  },
};

const later = counter.bump.bind(counter);

// 이 함수는 그대로 두세요
function press(times, step) {
  counter.count = 0;
  let last = 0;
  for (let i = 0; i < times; i += 1) last = later(step);
  return last;
}

function greet(greeting, mark) {
  return greeting + ', ' + this.name + '입니다' + mark;
}

function use(kind, target, args) {
  if (kind === 'call') {
    return greet.call(target, ...args);
  }

  if (kind === 'apply') {
    return greet.apply(target, args);
  }

  if (kind === 'bind') {
    const bound = greet.bind(target);
    return bound(...args);
  }

  if (kind === 'partial') {
    const partial = greet.bind(target, args[0]);
    return partial(...args.slice(1));
  }

  return '모르는 방식';
}
